?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Online orders · StepCure</title><link rel="stylesheet" href="<?= sc_url('themes/LT-367/assets/css/storefront.css') ?>"><style>body{font:15px Arial;background:#f5f4ed;color:#173e35}summary{cursor:pointer}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:12px;border-bottom:1px solid #173e3520}details{margin:20px 0}h2{font-size:22px}</style></head><body><main class="sc-store"><a href="<?= sc_url('admin/') ?>">← Admin dashboard</a><h1>Online orders</h1><p>Cash-on-delivery orders. Payment status remains unpaid until collection is confirmed through your operations process.</p><?php while($o=$orders->fetch_assoc()):$d=json_decode($o['delivery'],true);$items=sc_query('SELECT * FROM web_order_items WHERE order_id=?','i',[$o['id']])->get_result(); ?><details class="sc-panel"><summary><strong><?= sc_e($o['order_number']) ?></strong> · <?= sc_e($o['created_at']) ?> · <?= sc_money((int)round($o['total']*100)) ?> · <?= sc_e($o['status']) ?></summary><p><?= sc_e($o['email']) ?> · <?= sc_e($d['full_name']) ?> · <?= sc_e($d['phone']) ?></p><p><?= sc_e($d['address'].', '.$d['city'].', '.$d['state'].' '.$d['pin']) ?></p><table><thead><tr><th>Product</th><th>Quantity</th><th>Line total</th></tr></thead><tbody><?php while($i=$items->fetch_assoc()): ?><tr><td><?= sc_e($i['product_name']) ?></td><td><?= (int)$i['quantity'] ?></td><td><?= sc_money((int)round($i['line_total']*100)) ?></td></tr><?php endwhile; ?></tbody></table><p>Tax <?= sc_money((int)round($o['tax']*100)) ?> · Total <?= sc_money((int)round($o['total']*100)) ?> · <?= sc_e($o['payment_method'].' / '.$o['payment_status']) ?></p></details><?php endwhile; ?><a href="?p=<?= max(1,(int)($_GET['p']??1)-1) ?>">Previous</a> · <a href="?p=<?= max(1,(int)($_GET['p']??1))+1 ?>">Next</a></main></body></html>
